const FSM_ROOT_WORDS_PROBE: usize = ::core::mem::size_of::<ak_dfix_Probe>().div_ceil(8);
const FSM_ELEM_WORDS_PROBE: usize = 0;
/// Frames `Probe` can open at once: 1 (refused above FSM_MAX_FRAMES).
