/// D23: start an FSM decode of `buf` (valid and unmoved until the end event or an error) and write its FIRST event. Returns the event's op (AK_BDR_*; AK_BDR_APPLY, the root group, is the last), or < 0 = error.
#[no_mangle]
pub unsafe extern "C" fn ak_fsm_begin_ListMetricsResponse(ctx: *mut ak_dec_ctx, buf: *const u8, len: usize, ev: *mut ak_fsm_ev) -> i32 {
    // ABI v1 section 3: every entry point requires `ak_init`.
    #[cfg(feature = "init-guard")]
    if !crate::ak_init_ok() {
        return AK_ERR_UNINITIALIZED;
    }
    if ctx.is_null() || ev.is_null() { return AK_ERR_INVALID_STATE; }
    let dcx = ctx as *mut DecCtxImpl;
    ak_rt::bump!((*dcx).c, forward);
    // A new operation clears the sticky slot (the rule of the other families).
    (*dcx).hdr.err = AK_OK;
    if (*dcx).root != 17 { (*dcx).hdr.err = AK_ERR_INVALID_STATE; return AK_ERR_INVALID_STATE; } crate::rearm_on_entry!(dcx, crate::generated::codec::UNK_LAYOUT_LISTMETRICSRESPONSE);
    let f = fsm_of(dcx);
    // R-D9: spans are (u32, u32), so a longer buffer is refused at entry.
    if len > u32::MAX as usize {
        f.state = ST_FAILED;
        (*dcx).hdr.err = AK_ERR_LIMIT;
        return AK_ERR_LIMIT;
    }
    f.start(buf, len, FSM_ROOT_WORDS_LISTMETRICSRESPONSE + FSM_ELEM_WORDS_LISTMETRICSRESPONSE);
    f.sk = f.utf8_skip;
    (f.grp.as_mut_ptr() as *mut ak_dfix_ListMetricsResponse).write(ak_dfix_ListMetricsResponse::ZERO);
    fsm_step_list_metrics_response(dcx, f, ev)
}

/// D23: write the next event; returns its op or < 0. AK_ERR_INVALID_STATE after the root group or an error.
#[no_mangle]
pub unsafe extern "C" fn ak_fsm_next_ListMetricsResponse(ctx: *mut ak_dec_ctx, ev: *mut ak_fsm_ev) -> i32 {
    // ABI v1 section 3: every entry point requires `ak_init`.
    #[cfg(feature = "init-guard")]
    if !crate::ak_init_ok() {
        return AK_ERR_UNINITIALIZED;
    }
    if ctx.is_null() || ev.is_null() { return AK_ERR_INVALID_STATE; }
    let dcx = ctx as *mut DecCtxImpl;
    ak_rt::bump!((*dcx).c, forward);
    if (*dcx).root != 17 { return AK_ERR_INVALID_STATE; }
    let f = match (*dcx).fsm.as_deref_mut() {
        Some(f) if f.state == ST_RUN => f,
        // Never begun, ended, or failed: refused.
        _ => return AK_ERR_INVALID_STATE,
    };
    // The host failed the operation between two events (ak_fail): it ends here.
    if (*dcx).hdr.err != AK_OK { f.state = ST_FAILED; return (*dcx).hdr.err; }
    fsm_step_list_metrics_response(dcx, f, ev)
}

/// D23: COPY the D20 mask for every later FSM decode on this context (NULL = all zero); separate from the pull family's. AK_ERR_INVALID_STATE for a context bound to another root.
#[no_mangle]
pub unsafe extern "C" fn ak_fsm_set_pvt_ListMetricsResponse(ctx: *mut ak_dec_ctx, pvt: *const ak_pvt_ListMetricsResponse) -> i32 {
    // ABI v1 section 3: every entry point requires `ak_init`.
    #[cfg(feature = "init-guard")]
    if !crate::ak_init_ok() {
        return AK_ERR_UNINITIALIZED;
    }
    if ctx.is_null() { return AK_ERR_INVALID_STATE; }
    let dcx = ctx as *mut DecCtxImpl;
    if (*dcx).root != 17 { return AK_ERR_INVALID_STATE; }
    fsm_of(dcx).utf8_skip = if pvt.is_null() { 0 } else { (*pvt).utf8_skip };
    AK_OK
}

/// `UploadResultDataMessage`'s root group, in words; then the largest non-leaf element group.
const FSM_ROOT_WORDS_UPLOADRESULTDATAMESSAGE: usize = ::core::mem::size_of::<ak_dfix_UploadResultDataMessage>().div_ceil(8);
const FSM_ELEM_WORDS_UPLOADRESULTDATAMESSAGE: usize = 0;
/// Frames `UploadResultDataMessage` can open at once: 2 (refused above FSM_MAX_FRAMES).
const _: () = assert!(2 <= FSM_MAX_FRAMES);

